INSERT INTO email_send_attempts (
    email_draft_id, gmail_connection_id, request_key, message_id_header
)
SELECT draft.id, #{gmailConnectionId}, #{requestKey}, #{messageIdHeader}
FROM email_drafts AS draft
WHERE draft.id = #{emailDraftId}
  AND draft.email_drafts_status = 'FINALIZED'
ON CONFLICT DO NOTHING
